import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    info = {}       # id -> {'side':..., 'price':..., 'qty':..., 'active':bool}
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in info and info[oid]['active']:
                info[oid]['active'] = False
            continue

        if typ in ('limit', 'ioc'):
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty
        info[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            if side == 'buy':
                top_price, top_seq, top_id = opp_heap[0]
            else:
                neg_price, top_seq, top_id = opp_heap[0]
                top_price = -neg_price

            # skip inactive/filled
            if top_id not in info or not info[top_id]['active'] or info[top_id]['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            # check crossing condition
            if typ == 'market':
                crosses = True
            else:
                if side == 'buy':
                    crosses = price >= top_price
                else:
                    crosses = price <= top_price

            if not crosses:
                break

            resting_qty = info[top_id]['qty']
            trade_qty = min(remaining, resting_qty)
            trade_price = top_price

            if side == 'buy':
                buy_id = oid
                sell_id = top_id
            else:
                buy_id = top_id
                sell_id = oid

            trades.append([buy_id, sell_id, trade_price, trade_qty])

            remaining -= trade_qty
            info[top_id]['qty'] -= trade_qty
            info[oid]['qty'] = remaining

            if info[top_id]['qty'] <= 0:
                info[top_id]['active'] = False
                heapq.heappop(opp_heap)
            # else keep at front, since price-time priority: it stays at top for next iteration
            # but remaining==0 will end loop anyway if we filled incoming order

        # after matching, handle resting for limit orders
        if typ == 'limit' and remaining > 0:
            info[oid]['qty'] = remaining
            info[oid]['active'] = True
            s = next_seq()
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, s, oid))
            else:
                heapq.heappush(sell_heap, (price, s, oid))
        else:
            # ioc/market leftover discarded, or limit fully filled
            if remaining <= 0:
                info[oid]['active'] = False
            else:
                # ioc or market with leftover - discard
                info[oid]['active'] = False
                info[oid]['qty'] = 0

    return trades

